// Generated by Grumpy's Rusty Platform for VS Code.
//
// Two jobs: say so when the Xtensa linker is not on PATH, and add the linker script
// every esp-hal image needs.

fn main() {
    check_xtensa_linker();
    // Must be the last linker script, and the only one an esp-hal image needs: the
    // ESP-IDF bootloader owns the flash layout, so there is no memory.x here.
    println!("cargo:rustc-link-arg=-Tlinkall.x");
}

/// Xtensa cannot be linked by LLVM's own linker: it needs the GCC toolchain that comes
/// with espup, which only appears on PATH after `source $HOME/export-esp.sh`.
///
/// This **warns** rather than panics (0.19.23). `cargo check` never links, and that is
/// what rust-analyzer runs: panicking there failed the whole project on a toolchain the
/// check was never going to use, so every file showed this message instead of its type
/// errors. A real build still fails -- one step later, with the linker's own words --
/// and these lines are printed directly above that error.
fn check_xtensa_linker() {
    println!("cargo:rerun-if-env-changed=PATH");

    let target = std::env::var("TARGET").unwrap_or_default();
    let env_var = format!(
        "CARGO_TARGET_{}_LINKER",
        target.replace('-', "_").to_ascii_uppercase()
    );
    println!("cargo:rerun-if-env-changed={env_var}");

    let linker = std::env::var(&env_var).unwrap_or_else(|_| {
        target
            .strip_prefix("xtensa-")
            .and_then(|rest| rest.strip_suffix("-none-elf"))
            .map(|chip| format!("xtensa-{chip}-elf-gcc"))
            .unwrap_or_else(|| "xtensa-esp32-elf-gcc".to_string())
    });

    if std::process::Command::new(&linker).arg("--version").output().is_err() {
        println!("cargo:warning=Xtensa linker `{linker}` is not on PATH, so this will not link.");
        println!("cargo:warning=Install it with `espup install --targets esp32,esp32s3`, then run `source $HOME/export-esp.sh` before building. Checking (and rust-analyzer) does not need it.");
    }
}
